      kind: 'utxo',
      status: function () { return get('/api/status'); },
      blocks: function (o) { return get('/api/blocks', o); },
      txs: function (o) { return get('/api/txs', o); },
      holders: function (o) { return get('/api/holders', o); },
      miners: function (o) { return get('/api/miners', o); },
